const goldRes = await api.get('/customers', { tier: 'gold' });
const mailRes = await api.get('/mails', { label: 'refund' });
const goldIds = new Set(goldRes.items.map(c => c.id));
const names = mailRes.items
  .filter(m => m.customer_id && goldIds.has(m.customer_id))
  .map(m => {
    // find name from gold customers list
    const cust = goldRes.items.find(c => c.id === m.customer_id);
    return cust ? cust.name : null;
  })
  .filter(Boolean);
return Array.from(new Set(names));

const goldRes = await api.get('/customers', { tier: 'gold' });
const mailRes = await api.get('/mails', { label: 'refund' });
console.log('gold count', goldRes.count);
console.log('mail count', mailRes.count);
const goldMap = new Map(goldRes.items.map(c=>[c.id,c.name]));
const names = [];
for(const m of mailRes.items){
  if(m.customer_id && goldMap.has(m.customer_id)){
    names.push(goldMap.get(m.customer_id));
  }
}
const unique = [...new Set(names)];
console.log('unique names', unique);
return unique;

